'use client';

import React, { useState, useEffect } from 'react';
import dynamic from 'next/dynamic';
import {
  Sparkles,
  Eraser,
  Settings2,
  BookMarked,
  PlayCircle,
  PauseCircle,
  StopCircle,
  Menu,
  ImagePlus,
  Library,
  Type
} from 'lucide-react';
import FontManager from '@/components/FontManager';
import {
  ImageInput,
  EpubReader,
  VoiceInput,
  LibraryBrowser
} from '@/components/InputMethods';
import { useAppStore } from '@/store/useAppStore';
import { useVocabStore } from '@/store/useVocabStore';
import { ttsManager } from '@/lib/tts/manager';
import SettingsModal from '@/components/SettingsModal';
import VocabExport from '@/components/VocabExport';
import clsx from 'clsx';

// Dynamic import for TextAnalyzer to avoid SSR issues with kuroshiro
const TextAnalyzer = dynamic(() => import('@/components/TextAnalyzer'), {
  ssr: false,
  loading: () => (
    <div className="flex flex-col items-center justify-center py-16 text-gray-400">
      <div className="w-8 h-8 border-2 border-gray-200 border-t-blue-500 rounded-full animate-spin mb-4" />
      <p className="text-sm">銈炽兂銉濄兗銉嶃兂銉堛倰瑾伩杈笺伩涓?..</p>
    </div>
  ),
});

export default function Home() {
  const {
    inputText, setInputText,
    isAnalyzing,
    isSpeaking, setIsSpeaking,
    isPaused, setIsPaused,
    setSpeakingTokenId
  } = useAppStore();
  const { vocabList } = useVocabStore();
  const [showSettings, setShowSettings] = useState(false);
  const [showVocab, setShowVocab] = useState(false);
  const [analyzeKey, setAnalyzeKey] = useState(0);
  const [mounted, setMounted] = useState(false);
  const [inputMode, setInputMode] = useState<'text' | 'image' | 'epub' | 'library'>('text');

  useEffect(() => {
    setMounted(true);
  }, []);

  const handleAnalyze = () => {
    setAnalyzeKey(prev => prev + 1);
  };

  const handlePlayAll = () => {
    if (isSpeaking) {
      if (isPaused) {
        ttsManager.resume();
        setIsPaused(false);
      } else {
        ttsManager.pause();
        setIsPaused(true);
      }
    } else {
      setIsSpeaking(true);
      setIsPaused(false);
    }
  };

  const handleStop = () => {
    ttsManager.stop();
    setIsSpeaking(false);
    setIsPaused(false);
    setSpeakingTokenId(null);
  };

  const handleClear = () => {
    setInputText('');
    setAnalyzeKey(prev => prev + 1);
  };

  if (!mounted) {
    return null;
  }

  return (
    <main className="min-h-screen pb-20 md:pb-0">
      <FontManager />

      {/* Header */}
      <header className="bg-white/80 backdrop-blur-md border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-4xl mx-auto px-4 h-14 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-gradient-to-br from-rose-500 to-pink-600 p-1.5 rounded-lg shadow-sm">
              <span className="font-bold text-white text-sm px-1">瑾?/span>
            </div>
            <h1 className="text-lg font-bold tracking-tight text-gray-900">
              YOMI <span className="font-normal text-gray-400 text-sm">| Reader</span>
            </h1>
          </div>

          <div className="flex items-center gap-1">
            <button
              onClick={() => setShowVocab(true)}
              className="relative p-2 rounded-lg text-gray-400 hover:bg-gray-100 hover:text-gray-600 transition-colors"
              title="鍗樿獮甯砛

w-5 h-5" />
              {vocabList.length > 0 && (
                <span className="absolute -top-0.5 -right-0.5 w-4 h-4 bg-rose-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center">
                  {vocabList.length > 99 ? '99+' : vocabList.length}
                </span>
              )}
            </button>
            <button
              onClick={() => setShowSettings(true)}
              className="p-2 rounded-lg text-gray-400 hover:bg-gray-100 hover:text-gray-600 transition-colors"
              title="瑷畾"
            >
              <Settings2 className="w-5 h-5" />
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 mt-6">
        {/* Input Mode Tabs - Refactored for cleaner look */}
        <div className="flex gap-2 mb-2 overflow-x-auto pb-1 scrollbar-hide">
          <BookButton
            isActive={inputMode === 'text'}
            onClick={() => setInputMode('text')}
            icon={Type}
            label="銉嗐偔銈广儓"
          />
          <BookButton
            isActive={inputMode === 'image'}
            onClick={() => setInputMode('image')}
            icon={ImagePlus}
            label="OCR"
          />
          <BookButton
            isActive={inputMode === 'epub'}
            onClick={() => setInputMode('epub')}
            icon={BookMarked}
            label="闆诲瓙鏇哥睄 (EPUB)"
          />
          <BookButton
            isActive={inputMode === 'library'}
            onClick={() => setInputMode('library')}
            icon={Library}
            label="闈掔┖鏂囧簱"
          />

        </div>

        {/* Input Area */}
        <div className="group relative bg-white rounded-xl shadow-sm border border-gray-200 p-1 mb-8 focus-within:ring-2 focus-within:ring-blue-100 transition-all">
          {inputMode === 'text' ? (
            <textarea
              className="w-full h-32 p-4 rounded-lg resize-y outline-none text-base text-gray-700 placeholder-gray-300 bg-transparent"
              placeholder="鏃ユ湰瑾炪儐銈偣銉堛倰銇撱亾銇叆鍔涖仐銇︺亸銇犮仌銇?.."
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
            />
          ) : inputMode === 'image' ? (
            <div className="p-1">
              <ImageInput
                onTextExtracted={(text) => {
                  setInputText(text);
                  setInputMode('text');
                }}
              />
            </div>
          ) : inputMode === 'epub' ? (
            <div className="p-1">
              <EpubReader
                onTextExtracted={(text) => {
                  setInputText(text);
                  setInputMode('text');
                }}
              />
            </div>
          ) : (
            <div className="p-1">
              <LibraryBrowser
                onTextLoaded={(text) => {
                  setInputText(text);
                  setInputMode('text');
                }}
              />
            </div>
          )}

          {inputMode === 'text' && (
            <div className="flex items-center justify-between px-3 pb-2">
              <div className="text-xs text-gray-300 font-mono">
                {inputText.length} 鏂囧瓧
              </div>
              <div className="flex gap-2">
                <button
                  onClick={handleClear}
                  className="p-2 text-gray-300 hover:text-gray-500 transition-colors"
                  title="銈儶銈

w-4 h-4" />
                </button>
                <div className="border-l border-gray-100 h-4 mx-1" />
                <VoiceInput onResult={(text) => setInputText(inputText + text)} />
                <button
                  onClick={handleAnalyze}
                  disabled={isAnalyzing || !inputText.trim()}
                  className="bg-slate-900 hover:bg-slate-800 text-white px-4 py-1.5 rounded-lg text-sm font-medium transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                >
                  <Sparkles className="w-3.5 h-3.5" />
                  鍒嗘瀽
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Reader View Header */}
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-sm font-bold text-gray-400 uppercase tracking-wider">
            Reading View
          </h2>
          <div className="flex gap-2">
            {isSpeaking && (
              <button
                onClick={handleStop}
                className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-full transition-colors bg-gray-100 text-gray-500 hover:bg-gray-200 hover:text-gray-700"
              >
                <StopCircle className="w-3.5 h-3.5" />
                鍋滄
              </button>
            )}
            <button
              onClick={handlePlayAll}
              disabled={!inputText.trim()}
              className={clsx(
                "flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-full transition-colors",
                isSpeaking && !isPaused
                  ? "bg-amber-100 text-amber-700 hover:bg-amber-200"
                  : "bg-indigo-50 text-indigo-600 hover:bg-indigo-100",
                !inputText.trim() && "opacity-50 cursor-not-allowed"
              )}
            >
              {isSpeaking && !isPaused ? (
                <>
                  <PauseCircle className="w-3.5 h-3.5" />
                  涓€鏅傚仠姝n                </>
              ) : (
                <>
                  <PlayCircle className="w-3.5 h-3.5" />
                  {isPaused ? '鍐嶉枊' : '鍐嶇敓'}
                </>
              )}
            </button>
          </div>
        </div>

        {/* Text Analyzer */}
        {inputText.trim() && (
          <TextAnalyzer key={analyzeKey} text={inputText} />
        )}

        {!inputText.trim() && (
          <div className="text-center py-16 text-gray-400 bg-white rounded-xl border border-dashed border-gray-200">
            <p className="text-lg mb-2">鏃ユ湰瑾炪儐銈偣銉堛倰鍏ュ姏銇椼仸銇忋仩銇曘亜</p>
            <p className="text-sm text-gray-300">
              鍒嗘瀽銉溿偪銉炽倰銈儶銉冦偗銇欍倠銇ㄣ€佸崢瑾炪仈銇ㄣ伀鍒嗚В銇曘倢銇俱仚
            </p>
          </div>
        )}

        <div className="h-20" /> {/* Spacer for bottom panel */}
      </main>

      {/* Modals */}
      <SettingsModal isOpen={showSettings} onClose={() => setShowSettings(false)} />
      <VocabExport isOpen={showVocab} onClose={() => setShowVocab(false)} />
    </main>
  );
}

// Sub-components
function BookButton({ isActive, onClick, icon: Icon, label }: { isActive: boolean; onClick: () => void; icon: any; label: string }) {
  return (
    <button
      onClick={onClick}
      className={clsx(
        "px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 whitespace-nowrap",
        isActive
          ? "bg-slate-900 text-white"
          : "bg-white text-gray-500 hover:bg-gray-50 border border-gray-200"
      )}
    >
      <Icon className="w-4 h-4" />
      {label}
    </button>
  );
}

'use client';

import React, { useState } from 'react';
import { X, Volume2, Star, StarOff, BookOpen, ArrowRight } from 'lucide-react';
import { WordToken, PartOfSpeech, POS_COLORS } from '@/types';
import { useAppStore } from '@/store/useAppStore';
import { useVocabStore } from '@/store/useVocabStore';
import { getDeinflectedForm } from '@/lib/nlp/analyzer';
import { ttsManager } from '@/lib/tts/manager';
import clsx from 'clsx';
import PitchAccent from './PitchAccent';

import { searchDictionary } from '@/lib/dictionary';
import { DictionaryEntry } from '@/types';

interface InfoPanelProps {
    token: WordToken | null;
    onClose: () => void;
}

export default function InfoPanel({ token, onClose }: InfoPanelProps) {
    const { currentSentence, settings } = useAppStore();
    const { addVocab, isWordSaved, removeVocab, vocabList } = useVocabStore();
    const [isSpeaking, setIsSpeaking] = useState(false);
    const [dictEntry, setDictEntry] = useState<DictionaryEntry | null>(null);
    const [dictLang, setDictLang] = useState<'en' | 'jp' | 'zh'>('jp');
    const [isLoadingDict, setIsLoadingDict] = useState(false);

    React.useEffect(() => {
        if (token) {
            setIsLoadingDict(true);
            const base = getDeinflectedForm(token);
            // Map lang to provider
            let provider: 'jisho' | 'weblio_jj' | 'weblio_cj' = 'weblio_jj';
            if (dictLang === 'en') provider = 'jisho';
            if (dictLang === 'zh') provider = 'weblio_cj';

            searchDictionary(base, provider).then(entry => {
                setDictEntry(entry);
            }).finally(() => {
                setIsLoadingDict(false);
            });
        } else {
            setDictEntry(null);
        }
    }, [token, dictLang]);

    if (!token) return null;

    const baseForm = getDeinflectedForm(token);
    const isInflected = baseForm !== token.surface;
    const isSaved = isWordSaved(token.surface, token.reading);
    const colorScheme = POS_COLORS[token.pos] || POS_COLORS[PartOfSpeech.OTHER];

    const handleSpeak = () => {
        setIsSpeaking(true);
        ttsManager.speak(
            token.surface,
            settings,
            {
                onStart: () => setIsSpeaking(true),
                onEnd: () => setIsSpeaking(false)
            }
        );
    };

    const handleSaveVocab = () => {
        if (isSaved) {
            const item = vocabList.find(v => v.word === token.surface && v.reading === token.reading);
            if (item) removeVocab(item.id);
        } else {
            const meaning = dictEntry
                ? dictEntry.meanings.map(m => m.glosses.join(', ')).join('; ')
                : '(鎰忓懗銇岃銇ゃ亱銈娿伨銇涖倱銇с仐銇?';

            addVocab({
                word: token.surface,
                reading: token.reading || token.surface,
                baseForm,
                meaning,
                pos: token.pos,
                pitch: token.pitch,
                context: currentSentence,
            });
        }
    };

    return (
        <>
            {/* Backdrop for explicit click-outside dismissal */}
            <div
                className="fixed inset-0 z-40 bg-transparent"
                onClick={onClose}
            />

            <div
                className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-xl border-t border-gray-200 shadow-2xl z-50 animate-in slide-in-from-bottom-5 duration-300 flex flex-col h-[40vh] md:h-[35vh]"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Global Close Button (Top Right) */}
                <button
                    onClick={onClose}
                    className="absolute top-3 right-3 p-1.5 hover:bg-gray-200 rounded-full text-gray-500 transition-colors z-[60]"
                    title="闁夈仒銈媆

w-5 h-5" />
                </button>

                <div className="max-w-4xl mx-auto w-full flex flex-row h-full">

                    {/* Left Column: Word Info */}
                    <div className="p-5 md:w-1/3 flex flex-col gap-3 border-r border-gray-100 bg-gray-50/80 shrink-0">
                        {/* Header: POS */}
                        <div className="flex justify-between items-start">
                            <span className={clsx(
                                "px-2 py-0.5 text-[10px] font-bold rounded uppercase tracking-wider shadow-sm",
                                colorScheme.bg, colorScheme.text
                            )}>
                                {token.pos}
                            </span>
                        </div>

                        {/* Word Display */}
                        <div className="flex flex-col flex-1 justify-center items-center -mt-2">
                            <div className="relative pt-3 w-fit">
                                {token.pitch && token.pitch.length > 0 && (
                                    <div className="absolute top-0 left-1/2 -translate-x-1/2 opacity-80 scale-90">
                                        <PitchAccent pattern={token.pitch} />
                                    </div>
                                )}
                                <h2 className="text-3xl font-black text-gray-800 tracking-tight leading-none text-center">
                                    {token.surface}
                                </h2>
                            </div>
                            <div className="flex flex-col items-center mt-1">
                                <span className="text-base text-indigo-600 font-medium leading-tight">
                                    {token.reading || token.surface}
                                </span>
                                <span className="text-[10px] text-gray-400 font-mono tracking-wide uppercase mt-0.5">
                                    {token.romaji}
                                </span>
                            </div>
                        </div>

                        {/* Actions */}
                        <div className="flex gap-2 justify-center mb-1">
                            <button
                                onClick={handleSpeak}
                                disabled={isSpeaking}
                                className={clsx(
                                    "flex items-center justify-center w-8 h-8 rounded-full transition-all shadow-sm border",
                                    isSpeaking
                                        ? "bg-indigo-100 text-indigo-600 border-indigo-200"
                                        : "bg-white text-gray-600 border-gray-200 hover:border-indigo-300 hover:text-indigo-600"
                                )}
                                title="鐧洪煶"
                            >
                                <Volume2 className="w-4 h-4" />
                            </button>
                            <button
                                onClick={handleSaveVocab}
                                className={clsx(
                                    "flex items-center justify-center w-8 h-8 rounded-full transition-all shadow-sm border",
                                    isSaved
                                        ? "bg-amber-100 text-amber-600 border-amber-200"
                                        : "bg-white text-gray-600 border-gray-200 hover:border-amber-300 hover:text-amber-600"
                                )}
                                title="淇濆瓨"
                            >
                                {isSaved ? <Star className="w-4 h-4 fill-current" /> : <Star className="w-4 h-4" />}
                            </button>
                            <a
                                href={`https://jisho.org/search/${baseForm}`}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="flex items-center justify-center w-8 h-8 rounded-full bg-white text-gray-600 border border-gray-200 hover:border-blue-300 hover:text-blue-600 transition-all shadow-sm"
                                title="Jisho.org"
                            >
                                <BookOpen className="w-4 h-4" />
                            </a>
                        </div>
                    </div>

                    {/* Right Column: Definitions */}
                    <div className="flex-1 flex flex-col min-h-0 bg-white relative">
                        {/* Header: Tabs */}
                        <div className="px-5 py-3 border-b border-gray-100 flex items-center justify-between bg-white sticky top-0 z-10 pr-12">
                            <div className="flex bg-gray-100 p-0.5 rounded-lg border border-gray-200">
                                {[
                                    { id: 'en', label: 'EN' },
                                    { id: 'jp', label: 'JP' },
                                    { id: 'zh', label: 'ZH' }
                                ].map((lang) => (
                                    <button
                                        key={lang.id}
                                        onClick={() => setDictLang(lang.id as any)}
