                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">瀛椾綋椋庢牸</h3>
                                <div className="bg-white p-1 rounded-xl border border-gray-100 shadow-sm flex gap-1">
                                    {[
                                        { id: 'sans', label: '榛戜綋 (Sans)', font: 'font-sans' },
                                        { id: 'serif', label: '瀹嬩綋 (Serif)', font: 'font-serif' }
