}

// ------------------------------------------------------------------
// Sub-components for cleaner code
// ------------------------------------------------------------------

function SettingToggle({ icon, label, description, checked, onChange }: { icon: React.ReactNode, label: string, description: string, checked: boolean, onChange: () => void }) {
    return (
