'use client';

import React, { useState } from 'react';
import { Download, FileText, CreditCard, X, Trash2 } from 'lucide-react';
import { useVocabStore, exportToCSV, exportToAnkiTSV } from '@/store/useVocabStore';
import clsx from 'clsx';

interface VocabExportProps {
    isOpen: boolean;
    onClose: () => void;
}

export default function VocabExport({ isOpen, onClose }: VocabExportProps) {
    const { vocabList, clearVocab, removeVocab } = useVocabStore();
    const [showClearConfirm, setShowClearConfirm] = useState(false);

    if (!isOpen) return null;

    const handleExportCSV = () => {
        const csv = exportToCSV(vocabList);
        downloadFile(csv, 'yomi-vocab.csv', 'text/csv');
    };

    const handleExportAnki = () => {
        const tsv = exportToAnkiTSV(vocabList);
        downloadFile(tsv, 'yomi-vocab-anki.txt', 'text/plain');
    };

    const downloadFile = (content: string, filename: string, mimeType: string) => {
        const blob = new Blob(['\ufeff' + content], { type: `${mimeType};charset=utf-8` });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    const handleClearAll = () => {
        clearVocab();
        setShowClearConfirm(false);
    };

    return (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[80vh] overflow-hidden">
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-gray-100">
                    <h2 className="text-lg font-bold text-gray-900">鍗樿獮甯?/h2>
                    <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
                        <X className="w-5 h-5 text-gray-500" />
                    </button>
                </div>

                {/* Stats & Actions */}
                <div className="p-4 bg-gray-50 border-b border-gray-100">
                    <div className="flex items-center justify-between">
                        <div className="text-sm text-gray-600">
                            淇濆瓨娓堛伩: <span className="font-bold text-gray-900">{vocabList.length}</span> 鍗樿獮
                        </div>
                        <div className="flex gap-2">
                            <button
                                onClick={handleExportCSV}
                                disabled={vocabList.length === 0}
                                className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-500 text-white text-sm font-medium rounded-lg hover:bg-emerald-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                <FileText className="w-4 h-4" />
                                CSV
                            </button>
                            <button
                                onClick={handleExportAnki}
                                disabled={vocabList.length === 0}
                                className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-500 text-white text-sm font-medium rounded-lg hover:bg-blue-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                <CreditCard className="w-4 h-4" />
                                Anki
                            </button>
                            <button
                                onClick={() => setShowClearConfirm(true)}
                                disabled={vocabList.length === 0}
                                className="flex items-center gap-1.5 px-3 py-1.5 bg-red-500 text-white text-sm font-medium rounded-lg hover:bg-red-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                <Trash2 className="w-4 h-4" />
                                鍏ㄥ墛闄r
                            </button>
                        </div>
                    </div>
                </div>

                {/* Vocab List */}
                <div className="overflow-y-auto max-h-[50vh] p-4">
                    {vocabList.length === 0 ? (
                        <div className="text-center py-12 text-gray-400">
                            <Download className="w-12 h-12 mx-auto mb-3 opacity-50" />
                            <p>鍗樿獮甯炽伅绌恒仹銇?/p>
                            <p className="text-sm mt-1">鍗樿獮銈掋偗銉儍銈仐銇?猸?銈掓娂銇欍仺淇濆瓨銇曘倢銇俱仚</p>
                        </div>
                    ) : (
                        <div className="space-y-2">
                            {vocabList.map((item) => (
                                <div
                                    key={item.id}
                                    className="flex items-center justify-between p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors group"
                                >
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-baseline gap-2">
                                            <span className="font-bold text-gray-900">{item.word}</span>
                                            <span className="text-gray-500 text-sm">{item.reading}</span>
                                            <span className="text-xs text-gray-400 bg-gray-200 px-1.5 py-0.5 rounded">
                                                {item.pos}
                                            </span>
                                        </div>
                                        <div className="text-sm text-gray-600 truncate">{item.meaning}</div>
                                        <div className="text-xs text-gray-400 truncate mt-1">{item.context}</div>
                                    </div>
                                    <button
                                        onClick={() => removeVocab(item.id)}
                                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full opacity-0 group-hover:opacity-100 transition-all"
                                    >
                                        <X className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* Clear Confirmation */}
                {showClearConfirm && (
                    <div className="absolute inset-0 bg-black/50 flex items-center justify-center p-4">
                        <div className="bg-white rounded-xl p-6 max-w-sm w-full shadow-2xl">
                            <h3 className="text-lg font-bold text-gray-900 mb-2">鍏ㄣ仸銇崢瑾炪倰鍓婇櫎銇椼伨銇欍亱锛?/h3>
                            <p className="text-sm text-gray-600 mb-4">銇撱伄鎿嶄綔銇彇銈婃秷銇涖伨銇涖倱銆?/p>
                            <div className="flex gap-2 justify-end">
                                <button
                                    onClick={() => setShowClearConfirm(false)}
                                    className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                                >
                                    銈儯銉炽偦銉玕r
                                </button>
                                <button
                                    onClick={handleClearAll}
                                    className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors"
                                >
                                    鍏ㄥ墛闄r
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import clsx from 'clsx';
import { WordToken, PartOfSpeech, POS_COLORS } from '@/types';
import { useAppStore } from '@/store/useAppStore';
import { COLOR_THEMES } from '@/lib/colorThemes';
import PitchAccent from './PitchAccent';

interface WordTokenProps {
    token: WordToken;
    onSelect: (token: WordToken) => void;
    isSelected?: boolean;
    isSpeaking?: boolean;
}

export default function WordTokenComponent({ token, onSelect, isSelected, isSpeaking }: WordTokenProps) {
    // Get settings
    const { settings } = useAppStore();

    // Determine color scheme
    // If POS is NOT in activeColorPOS list, force it to 'default' (black/transparent)
    // Use optional chaining and default to empty array to handle initial state mismatch
    const isColorEnabled = (settings.activeColorPOS || []).includes(token.pos);

    // Resolve theme colors
    // Default to 'standard' if theme not found
    const currentTheme = COLOR_THEMES[settings.colorTheme || 'standard'] || COLOR_THEMES.standard;
    const themeColors = currentTheme.colors[token.pos] || currentTheme.colors[PartOfSpeech.OTHER];

    const colorScheme = isColorEnabled ? themeColors : {
        bg: 'bg-transparent',
        text: 'text-gray-800',
        border: 'border-b border-transparent'
    };

    // Logic: Show Furigana?
    const hasFurigana = token.reading && token.reading.length > 0;
    const shouldHideDueToCommon = settings.hideCommonFurigana && token.isCommon;
    const shouldShowFurigana = settings.showFurigana && hasFurigana && !shouldHideDueToCommon;

    // Logic: Hide Particle for cloze practice?
    const isParticle = token.pos === PartOfSpeech.PARTICLE;
    const isHiddenParticle = settings.hideParticles && isParticle;

    return (
        <div
            className={clsx(
                "relative inline-flex flex-col items-center mx-0.5 mb-2 group cursor-pointer select-none transition-all duration-200",
                isSelected && "scale-105 z-10"
            )}
            onClick={(e) => {
                e.stopPropagation();
                onSelect(token);
            }}
        >
            {/* Pitch Accent Visualization */}
            {settings.showPitchAccent && token.pitch && token.pitch.length > 0 && !isHiddenParticle && (
                <PitchAccent pattern={token.pitch} />
            )}

            {/* Furigana (Ruby text) */}
            <div className={clsx(
                "h-4 text-[10px] text-gray-500 font-medium whitespace-nowrap transition-opacity",
                shouldShowFurigana ? "opacity-70" : "opacity-0 group-hover:opacity-50"
            )}>
                {token.reading || '\u00A0'}
            </div>

            {/* Main Surface Text */}
            <div
                className={clsx(
                    "px-1.5 py-0.5 rounded text-lg font-medium transition-all duration-200 border-b-2",
                    isHiddenParticle
                        ? "text-transparent border-gray-300 bg-gray-100 min-w-[1em] hover:text-gray-400"
                        : [colorScheme.bg, colorScheme.text, colorScheme.border],
                    isSelected
                        ? "ring-2 ring-offset-1 ring-blue-400 shadow-md"
                        : isSpeaking && settings.karaokeMode
                            ? "bg-amber-100 ring-2 ring-offset-1 ring-amber-400"
                            : "border-transparent hover:brightness-95 hover:shadow-sm"
                )}
            >
                {token.surface}
            </div>

            {/* Cloze Mode Hint */}
            {isHiddenParticle && (
                <div className="absolute top-full mt-0.5 text-[10px] text-gray-400 opacity-0 group-hover:opacity-100 transition-opacity">
                    ?
                </div>
            )}
        </div>
    );
}

'use client';

import { AnalysisResult, SentenceAnalysis, PartOfSpeech, WordToken, PitchPattern, COMMON_WORDS } from '@/types';
import * as wanakana from 'wanakana';

// Dynamic imports for browser-only modules
let Kuroshiro: any = null;
let KuromojiAnalyzer: any = null;
let kuroshiroInstance: any = null;
let isInitializing = false;
let initPromise: Promise<void> | null = null;

// Initialize Kuroshiro with Kuromoji analyzer
async function initializeKuroshiro(): Promise<void> {
    if (kuroshiroInstance) return;
    if (initPromise) return initPromise;

    if (isInitializing) {
        // Wait for existing initialization
        return new Promise((resolve) => {
            const check = setInterval(() => {
                if (kuroshiroInstance) {
                    clearInterval(check);
                    resolve();
                }
            }, 100);
        });
    }

    isInitializing = true;

    initPromise = (async () => {
        try {
            // Dynamic imports for client-side only
            const kuroshiroModule = await import('kuroshiro');
            const analyzerModule = await import('kuroshiro-analyzer-kuromoji');

            Kuroshiro = kuroshiroModule.default;
            KuromojiAnalyzer = analyzerModule.default;

            kuroshiroInstance = new Kuroshiro();

            // Initialize with dictionary path pointing to public folder
            await kuroshiroInstance.init(new KuromojiAnalyzer({
                dictPath: '/dict'
            }));

            console.log('Kuroshiro initialized successfully');
        } catch (error) {
            console.error('Failed to initialize Kuroshiro:', error);
            isInitializing = false;
            initPromise = null;
            throw error;
        }
    })();

    return initPromise;
}

// Map Japanese POS to our enum
function mapPosToEnum(pos: string): PartOfSpeech {
    const posMap: Record<string, PartOfSpeech> = {
        '鍚嶈': PartOfSpeech.NOUN,
        '鍕曡': PartOfSpeech.VERB,
        '褰㈠瑭?: PartOfSpeech.ADJECTIVE,
        '褰㈠鍕曡': PartOfSpeech.ADJECTIVE,
        '鍔╄': PartOfSpeech.PARTICLE,
        '鍔╁嫊瑭?: PartOfSpeech.AUXILIARY,
        '鍓': PartOfSpeech.ADVERB,
        '鎺ョ稓瑭?: PartOfSpeech.CONJUNCTION,
        '鎰熷嫊瑭?: PartOfSpeech.INTERJECTION,
        '鎺ラ牠瑭?: PartOfSpeech.PREFIX,
        '鎺ュ熬瑭?: PartOfSpeech.SUFFIX,
        '瑷樺彿': PartOfSpeech.SYMBOL,
    };
    return posMap[pos] || PartOfSpeech.OTHER;
}

// Estimate pitch accent pattern (heuristic-based for MVP)
function estimatePitch(reading: string, pos: PartOfSpeech): { pattern: PitchPattern; accentMora: number } {
    if (!reading) return { pattern: [], accentMora: 0 };

    // Count morae (combining small kana with previous)
    const moras = reading.replace(/[銇併亙銇呫亣銇夈們銈呫倗銈庛仯]/g, '').length;
    if (moras === 0) return { pattern: [], accentMora: 0 };

    // Simple deterministic hash for consistent pitch in demo
    const hash = reading.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    const type = hash % 4;

    let pattern: number[] = [];
    let accentMora = 0;

    if (type === 0) {
        // Heiban (骞虫澘): L H H H...
        pattern = [0, ...Array(moras - 1).fill(1)];
        accentMora = 0;
    } else if (type === 1) {
        // Atamadaka (闋珮): H L L L...
        pattern = [1, ...Array(moras - 1).fill(0)];
        accentMora = 1;
    } else if (type === 2 && moras > 2) {
        // Nakadaka (涓珮): L H...H L L
        const peak = Math.floor(moras / 2);
        pattern = Array(moras).fill(0).map((_, i) => (i === 0 ? 0 : i <= peak ? 1 : 0));
        accentMora = peak + 1;
    } else {
        // Odaka (灏鹃珮): L H H H (drop after)
        pattern = [0, ...Array(moras - 1).fill(1)];
        accentMora = moras;
    }

    return { pattern, accentMora };
}

// Get de-inflected (dictionary) form
export function getDeinflectedForm(token: WordToken): string {
    if (token.baseForm && token.baseForm !== token.surface && token.baseForm !== '*') {
        return token.baseForm;
    }

    // Fallback rules for common conjugations
    const s = token.surface;
    if (token.pos === PartOfSpeech.VERB) {
        if (s.endsWith('銇俱仚')) return s.replace(/銇俱仚$/, '銈?);
        if (s.endsWith('銇俱仐銇?)) return s.replace(/銇俱仐銇?/, '銈?);
        if (s.endsWith('銇俱仜銈?)) return s.replace(/銇俱仜銈?/, '銈?);
        if (s.endsWith('銇亜')) return s.replace(/銇亜$/, '銈?);
        if (s.endsWith('銇熴亜')) return s.replace(/銇熴亜$/, '銈?);
        if (s.endsWith('銇?)) return s.replace(/銇?/, '銈?);
        if (s.endsWith('銇?)) return s.replace(/銇?/, '銈?);
    }

    return token.surface;
}

// Main analysis function
export async function analyzeJapaneseText(text: string): Promise<AnalysisResult> {
    await initializeKuroshiro();

    if (!kuroshiroInstance) {
        throw new Error('Kuroshiro not initialized');
    }

    // Split into sentences
    const rawSentences = text.split(/([銆傦紒锛焅
]+)/).filter(Boolean);
    const sentences: SentenceAnalysis[] = [];
    let currentStr = '';

    for (const part of rawSentences) {
        if (/[銆傦紒锛焅
]+/.test(part)) {
            currentStr += part;

            if (currentStr.trim()) {
                const sentenceAnalysis = await analyzeSentence(currentStr.trim(), sentences.length);
                sentences.push(sentenceAnalysis);
            }
            currentStr = '';
        } else {
            currentStr += part;
        }
    }

    // Handle remaining text without sentence ending
    if (currentStr.trim()) {
        const sentenceAnalysis = await analyzeSentence(currentStr.trim(), sentences.length);
        sentences.push(sentenceAnalysis);
    }

    return { sentences };
}

async function analyzeSentence(sentence: string, index: number): Promise<SentenceAnalysis> {
    // Get raw tokenization data from Kuroshiro's internal tokenizer
    const rawTokens = await kuroshiroInstance._analyzer.parse(sentence);

    const tokens: WordToken[] = await Promise.all(
        rawTokens.map(async (t: any, idx: number) => {
            const surface = t.surface_form;
            const readingKatakana = t.reading || surface;
            const readingHiragana = wanakana.toHiragana(readingKatakana);
            const pos = mapPosToEnum(t.pos);

            const { pattern, accentMora } = estimatePitch(readingHiragana, pos);

            // Determine if reading is redundant (surface is already kana)
            const isKanaOnly = wanakana.isHiragana(surface) || wanakana.isKatakana(surface);
            const reading = isKanaOnly ? '' : readingHiragana;

            const baseForm = t.basic_form !== '*' ? t.basic_form : surface;

            return {
                id: `${index}-${idx}-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
                surface,
                reading,
                romaji: wanakana.toRomaji(readingHiragana),
                pos,
                posDetail: t.pos_detail_1,
                baseForm,
                pitch: pattern,
                accentMora,
                isCommon: COMMON_WORDS.has(baseForm) || COMMON_WORDS.has(surface),
                conjugation: t.conjugated_type !== '*' ? t.conjugated_type : undefined,
            };
        })
    );

    // Post-process tokens to fix number + counter issues (e.g. 5鏃?-> itsuka)
    return {
        id: `sentence-${index}`,
        original: sentence,
        tokens: postProcessTokens(tokens, index),
    };
}

