import { TtsProvider } from './types';

interface SpeakOptions {
    voiceURI?: string;
    speed?: number;
    onStart?: () => void;
    onEnd?: () => void;
    onBoundary?: (charIndex: number) => void;
}

export class NativeTtsProvider implements TtsProvider {
    private utterance: SpeechSynthesisUtterance | null = null;
    private queue: string[] = [];
    private currentIndex = 0;
    private isPlaying = false;
    private charOffset = 0;
    private currentOptions: SpeakOptions = {};

    speak(text: string, options: SpeakOptions) {
        this.stop(); // Stop any previous playback

        if (!('speechSynthesis' in window)) {
            console.warn('Speech synthesis not supported');
            return;
        }

        this.currentOptions = options;
        this.queue = this.chunkText(text);
        this.currentIndex = 0;
        this.charOffset = 0;
        this.isPlaying = true;

        if (this.queue.length > 0) {
            // Trigger onStart only for the first chunk
            options.onStart && options.onStart();
            this.playNextChunk();
        } else {
            options.onEnd && options.onEnd();
        }
    }

    private chunkText(text: string): string[] {
        // Split by punctuation but keep the punctuation
        // Max chunk size ~200 chars to be safe (browsers vary, Chrome can do more but safer is better)
        const chunks: string[] = [];
        let currentChunk = '';

        // Split by common Japanese sentence terminators
        const sentences = text.split(/([銆傦紒锛焅
]+)/); // Include delimiters

        for (let i = 0; i < sentences.length; i++) {
            const part = sentences[i];

            if (currentChunk.length + part.length > 200) {
                if (currentChunk) chunks.push(currentChunk);
                currentChunk = part;
            } else {
                currentChunk += part;
            }
        }
        if (currentChunk) chunks.push(currentChunk);

        return chunks;
    }

    private playNextChunk() {
        if (!this.isPlaying || this.currentIndex >= this.queue.length) {
            this.isPlaying = false;
            this.currentOptions.onEnd && this.currentOptions.onEnd();
            return;
        }

        const chunkText = this.queue[this.currentIndex];

        // Skip silent/whitespace chunks manually to avoid browser inconsistencies
        if (!chunkText.trim()) {
            this.charOffset += chunkText.length;
            this.currentIndex++;
            // Use timeout to prevent stack overflow on many empty lines
            setTimeout(() => this.playNextChunk(), 0);
            return;
        }

        const u = new SpeechSynthesisUtterance(chunkText);
        u.lang = 'ja-JP';
        u.rate = this.currentOptions.speed || 1.0;

        if (this.currentOptions.voiceURI) {
            const voices = window.speechSynthesis.getVoices();
            const voice = voices.find(v => v.voiceURI === this.currentOptions.voiceURI);
            if (voice) u.voice = voice;
        }

        // We don't trigger onStart for subsequent chunks, only the first one (handled in speak)

        u.onend = () => {
            if (this.isPlaying) {
                this.charOffset += chunkText.length;
                this.currentIndex++;
                this.playNextChunk();
            }
        };

        u.onerror = (e) => {
            console.error('TTS Chunk Error:', e);
            // Try to continue to next chunk even if one fails
            if (this.isPlaying) {
                this.charOffset += chunkText.length;
                this.currentIndex++;
                this.playNextChunk();
            }
        };

        // Boundary event mapping
        u.onboundary = (event) => {
            if (event.name === 'word' && this.currentOptions.onBoundary) {
                // Map local chunk index to global text index
                this.currentOptions.onBoundary(this.charOffset + event.charIndex);
            }
        };

        this.utterance = u;
        window.speechSynthesis.speak(u);
    }

    stop() {
        this.isPlaying = false;
        this.queue = [];
        this.currentIndex = 0;
        if ('speechSynthesis' in window) {
            window.speechSynthesis.cancel();
        }
        this.utterance = null;
    }

    pause() {
        if ('speechSynthesis' in window) {
            window.speechSynthesis.pause();
            this.isPlaying = false; // "Logically" paused for our queue loop
        }
    }

    resume() {
        if ('speechSynthesis' in window) {
            // Restore state to allow onend to continue queue
            this.isPlaying = true;
            window.speechSynthesis.resume();
        }
    }

    async getVoices(): Promise<{ id: string; name: string }[]> {
        return new Promise((resolve) => {
            const voices = window.speechSynthesis.getVoices();
            if (voices.length > 0) {
                resolve(this._formatVoices(voices));
            } else {
                window.speechSynthesis.onvoiceschanged = () => {
                    resolve(this._formatVoices(window.speechSynthesis.getVoices()));
                };
            }
        });
    }

    private _formatVoices(voices: SpeechSynthesisVoice[]) {
        return voices
            .filter(v => v.lang.includes('ja') || v.lang.includes('JP'))
            .map(v => ({ id: v.voiceURI, name: v.name }));
    }
}

import { TtsProvider } from './types';

// Using Google Translate TTS as a lightweight "Online" fallback
// Note: This is unofficial and may be rate limited or blocked.
// It does NOT support boundary events, so karaoke won't look great (mock sync).

export class OnlineTtsProvider implements TtsProvider {
    private audio: HTMLAudioElement | null = null;
    private timer: NodeJS.Timeout | null = null;

    speak(text: string, options: {
        speed?: number;
        onStart?: () => void;
        onEnd?: () => void;
        onBoundary?: (charIndex: number) => void;
    }) {
        this.stop();

        // Google TTS URL (unofficial)
        // client=tw-ob is commonly used for these hacks
        const speed = options.speed || 1.0;
        const url = `https://translate.google.com/translate_tts?ie=UTF-8&q=${encodeURIComponent(text)}&tl=ja&client=tw-ob&ttsspeed=${speed}`;

        this.audio = new Audio(url);
        this.audio.playbackRate = speed; // Attempt to set rate on audio element

        this.audio.onplay = () => {
            options.onStart && options.onStart();

            // Mock Karaoke: advance cursor linearly based on text length and avg reading speed
            // Japanese avg: ~10 chars/sec?
            if (options.onBoundary) {
                const totalDuration = (text.length * 0.2) * 1000; // rough guess specific to this speed
                const interval = totalDuration / text.length;
                let charIndex = 0;

                this.timer = setInterval(() => {
                    if (charIndex < text.length) {
                        options.onBoundary!(charIndex);
                        charIndex++;
                    }
                }, interval);
            }
        };

        this.audio.onended = () => {
            this.clearTimer();
            options.onEnd && options.onEnd();
        };

        this.audio.onerror = (e) => {
            console.error('Online TTS Error', e);
            // Fallback to alert
            options.onEnd && options.onEnd();
        };

        this.audio.play().catch(e => {
            console.error("Audio playback failed", e);
            options.onEnd && options.onEnd();
        });
    }

    stop() {
        this.clearTimer();
        if (this.audio) {
            this.audio.pause();
            this.audio = null;
        }
    }

    pause() {
        if (this.audio) {
            this.audio.pause();
            if (this.timer) {
                clearInterval(this.timer); // Pause timer
            }
        }
    }

    resume() {
        if (this.audio) {
            this.audio.play().catch(console.error);
            // Resume timer logic would be complex here because of linear interpolation
            // For now, let's just not resume timer or reset it to simpler logic?
            // Actually, if we clear timer on pause, we need to restart it on resume with adjusted offset.
            // This is "Online" fallback (Google TTS) which is hacky encryption anyway
            // Let's just resume audio. 
        }
    }

    private clearTimer() {
        if (this.timer) {
            clearInterval(this.timer);
            this.timer = null;
        }
    }

    async getVoices(): Promise<{ id: string; name: string }[]> {
        return [{ id: 'google', name: 'Google Translate (Online)' }];
    }
}

import { TtsProvider } from './types';
import axios from 'axios';

// Interfaces for VOICEVOX API
interface VoicevoxSpeaker {
    name: string;
    speaker_uuid: string;
    styles: { name: string; id: number }[];
    version: string;
}

export class VoicevoxProvider implements TtsProvider {
    private audio: HTMLAudioElement | null = null;
    private currentRequestId: number = 0;

    async speak(text: string, options: {
        speakerId?: number;
        serverUrl?: string;
        speed?: number;
        onStart?: () => void;
        onEnd?: () => void;
        onBoundary?: (charIndex: number) => void;
    }) {
        // 1. Cancel previous playback immediately and invalidate pending requests
        this.stop();

        // 2. Increment request ID.
        const requestId = ++this.currentRequestId;

        const baseUrl = options.serverUrl || 'http://localhost:50021';
        const speaker = options.speakerId || 3; // Default to Zundamon Normal
        const speed = options.speed || 1.0;

        try {
            // 1. Create Audio Query
            // Using axios cancel token would be better, but logic check is safer for logic flow.
            const queryRes = await axios.post(`${baseUrl}/audio_query`, null, {
                params: { text, speaker }
            });

            if (this.currentRequestId !== requestId) return; // Obsolete

            const query = queryRes.data;
            query.speedScale = speed;

            // 2. Synthesize Audio
            const synthRes = await axios.post(`${baseUrl}/synthesis`, query, {
                params: { speaker },
                responseType: 'blob'
            });

            if (this.currentRequestId !== requestId) return; // Obsolete

            // 3. Create Audio URL
            const audioUrl = URL.createObjectURL(synthRes.data);
            this.audio = new Audio(audioUrl);

            this.audio.onplay = () => {
                if (this.currentRequestId === requestId) {
                    options.onStart && options.onStart();
                }
            };

            this.audio.onended = () => {
                if (this.currentRequestId === requestId) {
                    options.onEnd && options.onEnd();
                }
            };

            this.audio.onerror = (e) => {
                if (this.currentRequestId === requestId) {
                    console.error('Voicevox playback error', e);
                    options.onEnd && options.onEnd();
                }
            };

            this.audio.play();

        } catch (err) {
            if (this.currentRequestId !== requestId) return; // Ignore errors from old requests

            console.error('Voicevox Error:', err);
            // alert('VOICEVOX 杩炴帴澶辫触銆俓
璇风‘淇濆凡鎵撳紑 VOICEVOX 杞欢 (http://localhost:50021)');
            options.onEnd && options.onEnd();
        }
    }

    stop() {
        // Invalidate active request
        this.currentRequestId++;

        if (this.audio) {
            this.audio.pause();
            this.audio.currentTime = 0;
            this.audio = null;
        }
    }

    pause() {
        if (this.audio) {
            this.audio.pause();
        }
    }

    resume() {
        if (this.audio) {
            this.audio.play();
        }
    }

    async getVoices(): Promise<{ id: string; name: string }[]> {
        // This connects to local VOICEVOX to get text speakers
        try {
            const res = await axios.get('http://localhost:50021/speakers');
            const speakers: VoicevoxSpeaker[] = res.data;
            const voices: { id: string; name: string }[] = [];

            speakers.forEach(s => {
                s.styles.forEach(style => {
                    voices.push({
                        id: style.id.toString(),
                        name: `${s.name} (${style.name})`
                    });
                });
            });
            return voices;
        } catch (e) {
            return [{ id: '3', name: '杩炴帴澶辫触 (璇峰惎鍔╒OICEVOX)' }];
        }
    }
}

// Type declarations for kuroshiro and kuroshiro-analyzer-kuromoji

declare module 'kuroshiro' {
    interface KuroshiroOptions {
        mode?: 'normal' | 'spaced' | 'okurigana' | 'furigana';
        to?: 'hiragana' | 'katakana' | 'romaji';
        romajiSystem?: 'nippon' | 'passport' | 'hepburn';
    }

    class Kuroshiro {
        init(analyzer: any): Promise<void>;
        convert(text: string, options?: KuroshiroOptions): Promise<string>;
        _analyzer: {
            parse(text: string): Promise<any[]>;
        };
    }

    export default Kuroshiro;
}

declare module 'kuroshiro-analyzer-kuromoji' {
    interface AnalyzerOptions {
        dictPath?: string;
    }

    class Analyzer {
        constructor(options?: AnalyzerOptions);
        init(): Promise<void>;
        parse(text: string): Promise<any[]>;
    }

    export default Analyzer;
}
